fn logical_or(x1: Vec<bool>, x2: Vec<bool>) -> Vec<bool> {
    // Ensure both inputs have the same length
    assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");

    // Consume both vectors and compute element-wise OR
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a || b)
      .collect()
}

